class Solution:
    def minCostClimbingStairs(self, cost: List[int]) -> int:
        n = len(cost)

        @lru_cache
        def step(i: int) -> int:
            if i >= n:
                return 0
            return cost[i] + min(step(i + 1), step(i + 2))

        return min(step(0), step(1))

